{"function": "() => {
    // Find the "jingoism in Context" section
    const headings = Array.from(document.querySelectorAll('h2'));
    const contextHeading = headings.find(h => h.textContent.includes('jingoism in Context'));

    if (!contextHeading) return 'Section not found';

    // Get the paragraph after this heading
    let currentElement = contextHeading.nextElementSibling;
    let contextText = '';

    // Collect text until we hit another heading or separator
    while (currentElement && !currentElement.tagName.match(/^h[1-6]$/i) && !currentElement.classList.contains('separator')) {
        if (currentElement.textContent.trim()) {
            contextText += currentElement.textContent.trim() + '\n';
        }
        currentElement = currentElement.nextElementSibling;
    }

    return contextText || 'No context text found';
}"}

